    test('actual managed Git hook checks bundle before loading changed core',function(){var f=cliFixture();A.cli(['install-hooks','--source',f.source]);var sentinel=f.root+'/hook-core-executed',payload='ObjC.import("Foundation"); $.NSString.stringWithString("unsafe").writeToFileAtomicallyEncodingError('+JSON.stringify(sentinel)+',true,$.NSUTF8StringEncoding,Ref()); function run(){return "unsafe";}';write(f.config.bundle+'/att-core.js',payload);var r=A.exec(['/usr/bin/git','checkout','--detach',f.identity.commit],f.source,{env:{GIT_TERMINAL_PROMPT:'0'}});equal(0,r.code,'Hook caused Git checkout failure: '+r.stderr);assert(/changed/.test(r.stderr),'Managed hook did not detect altered core');assert(!A.exists(sentinel),'Hook loaded an unverified core');assert(!A.exists(f.config.store+'/worker-status.json'));A.ensureSourceClean(f.source);});
