    test('tool sources remain stable throughout test run',function(){Object.keys(loadedHashes).forEach(function(name){equal(loadedHashes[name],A.hashFile(base+'/'+name),'Tool source changed during test run: '+name);});});

    var selected=tests.filter(function(t){return !filter||t.name.toLowerCase().indexOf(filter.toLowerCase())>=0;});
    if(filter==='--list')return A.canonical({count:tests.length,names:tests.map(function(t){return t.name;})});
    assert(selected.length>0,'No cases match the requested filter');
    function report() { A.atomicJSON(root+'/script-test-results.json',{schema_version:1,recorded_at:new Date().toISOString(),runtime:'macOS system JXA / JavaScriptCore + Foundation',tools_directory:A.real(base),loaded_source_sha256:loadedHashes,evidence_directory:root,filter:filter,total:selected.length,completed:reports.length,passed:reports.filter(function(r){return r.status==='passed';}).length,failed:failures,elapsed_milliseconds:Date.now()-started,results:reports,limitations:['Windows PowerShell preparation and Windows activation are not executed by this macOS suite.','Store process probes in fixture activation are typed test functions; real Mac process probing is checked separately in public A/B acceptance.','No network or public artifact downloads occur in this fixture suite.']}); }
    selected.forEach(function(t){var start=Date.now(),result={name:t.name,status:'passed',fixture_directories:[],expected_refusals:[]};activeCase=result;try{t.fn();console.log('PASS '+t.name);}catch(e){failures++;result.status='failed';result.error=String(e);result.stack=e.stack?String(e.stack):'';console.log('FAIL '+t.name+' : '+e);}activeCase=null;result.milliseconds=Date.now()-start;reports.push(result);report();});
    var summary='Tests: '+selected.length+'; passed: '+(selected.length-failures)+'; failed: '+failures+'; seconds: '+((Date.now()-started)/1000).toFixed(3);console.log(summary);
    if(failures)throw new Error(summary+'; evidence: '+root+'/script-test-results.json');return summary;
